from re import match
from time import sleep, time
from typing import Any, Callable

from taf.rfrl.procedures.resources.python.bts.utils.pretty_logger import log_debug
from taf.rfrl.procedures.resources.python.bts.utils.exceptions import TimeExceeded, ResultError


def wait_for(expected_value: Any, abort_if: Any, timeout: int, callback: Callable, raise_exc: bool = True, **callback_kwargs: Any) -> bool:
    """
    Waits for callback to return expected value before timeout. Aborts immediately after callback returns abort value.
    :param expected_value: value which is expected to be returned by callback
    :param abort_if: value which, when returned by callback, cancels waiting for expected value
    :param timeout: time to wait (in seconds) for callback to return expected value
    :param callback: callable (function, method etc.) which, when called, should return expected value
    :param raise_exc: determines whether exception should be raised (True) or not (False) upon wait failure;
                      if turned off (False) then bool will be returned instead (True for success, False for failure);
                      defaults to True (exception will be raised upon wait failure)
    :param callback_kwargs: keyword arguments which will be passed to callback upon calling it;
                            i.e. action_id='12887254'
    :return: True if callback returns expected value before timeout;
             False if callback does not return expected value before timeout (or returns abort value) and raise_exc is set to False
    :raises TimeExceeded: if callback does not return expected value before timeout is reached and raise_exc is set to True
    :raises ResultError: if callback returns abort value and waiting is cancelled and raise_exc is set to True
    """
    callback_name = callback.__name__
    callback_kwargs_str = ', '.join([f'{key}={value}' for key, value in callback_kwargs.items()])
    log_debug(f'Waiting for {callback_name}({callback_kwargs_str}) to return {expected_value} '
              f'before {timeout}s timeout, aborting if {abort_if} returned')

    start_time = time()

    while True:
        result = callback(**callback_kwargs)

        if result == expected_value:
            log_debug(f'{callback_name}({callback_kwargs_str}) returned {expected_value}')
            return True

        if result == abort_if:
            msg = f'{callback_name}({callback_kwargs_str}) did not returned {expected_value} ' \
                  f'but {abort_if} instead, aborting'

            if raise_exc:
                raise ResultError(msg)
            else:
                log_debug(msg)
                return False

        if time() - start_time >= timeout:
            msg = f'{callback_name}({callback_kwargs_str}) did not returned {expected_value} ' \
                  f'before {timeout}s timeout but {result} instead'

            if raise_exc:
                raise TimeExceeded(msg)
            else:
                log_debug(msg)
                return False

        sleep(5)


def wait_for_not(value: Any, abort_if: Any, timeout: int, callback: Callable, raise_exc: bool = True, **callback_kwargs: Any) -> bool:
    """
    Waits for callback to return something other than given value before timeout. Aborts immediately after callback returns abort value.
    :param value: value which is expected to not be returned by callback
    :param abort_if: value which, when returned by callback, cancels waiting for something other than given value
    :param timeout: time to wait (in seconds) for callback to return something other than given value
    :param callback: callable (function, method etc.) which, when called, should return something other than given value
    :param raise_exc: determines whether exception should be raised (True) or not (False) upon wait failure;
                      if turned off (False) then bool will be returned instead (True for success, False for failure);
                      defaults to True (exception will be raised upon wait failure)
    :param callback_kwargs: keyword arguments which will be passed to callback upon calling it;
                            i.e. action_id='12887254'
    :return: True if callback returns something other than given value before timeout;
             False if callback does not return something other than given value before timeout (or returns abort value)
             and raise_exc is set to False
    :raises TimeExceeded: if callback does not return something other than given value before timeout is reached and raise_exc is set to True
    :raises ResultError: if callback returns abort value and waiting is cancelled and raise_exc is set to True
    """
    callback_name = callback.__name__
    callback_kwargs_str = ', '.join([f'{key}={value}' for key, value in callback_kwargs.items()])
    log_debug(f'Waiting for {callback_name}({callback_kwargs_str}) to return something other than {value} '
              f'before {timeout}s timeout, aborting if {abort_if} returned')

    start_time = time()

    while True:
        result = callback(**callback_kwargs)

        if result == abort_if:
            msg = f'{callback_name}({callback_kwargs_str}) did not returned something other than {value} ' \
                  f'but {abort_if} instead, aborting'

            if raise_exc:
                raise ResultError(msg)
            else:
                log_debug(msg)
                return False

        if result != value:
            log_debug(f'{callback_name}({callback_kwargs_str}) returned {result}')
            return True

        if time() - start_time >= timeout:
            msg = f'{callback_name}({callback_kwargs_str}) did not returned something other than {value} ' \
                  f'before {timeout}s timeout'

            if raise_exc:
                raise TimeExceeded(msg)
            else:
                log_debug(msg)
                return False

        sleep(5)


def is_in_utc_format(date_time: str) -> bool:
    """
    Checks, whether given date and time is in UTC format.
    :param date_time: date and time to be checked, i.e. '2024-10-04T07:37:21+00:00' or '04.10.2024 07:37:21'
    :return: True if date and time is in UTC format, False otherwise
    """
    utc_time_formats = [r'^[0-9]{2}\.[0-9]{2}\.\b[0-9]{4} [0-9]{2}:[0-9]{2}:[0-9]{2}$',
                        r'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}[+-][0-9]{2}:[0-9]{2}$']
    return any(match(utc_time_format, date_time) for utc_time_format in utc_time_formats)
